import { Switch } from '@refy-design/web';
import { ThemeProvider } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof Switch>, 'aria-label' | 'defaultChecked'> = {
    'aria-label': 'Turn on auto top-up',
    defaultChecked: false,
  };
  return (
    <ThemeProvider
      theme={{
        name: 'Switch measures',
        tokens: {
          '--switch-height': '24px',
          '--switch-width': '40px',
          '--switch-thumb-size': '16px',
          '--switch-thumb-inset': '4px',
          '--switch-track-off': 'var(--line)',
        },
      }}
    >
      <div
        data-testid="switch-measures"
        style={{ display: 'flex', gap: 'var(--space-3)' }}
      >
        <Switch {...args} aria-label="Off" />
        <Switch {...args} aria-label="On" defaultChecked />
      </div>
    </ThemeProvider>
  );
}
